def tokenize(text: str) -> list[str]: text = text.lower().replace(",", " ").replace("/", " ") return text.split()

def build_vocab(texts: list[str]) -> dict[str, int]: vocab = {"<PAD>": 0, "<UNK>": 1}

for text in texts: for token in tokenize(text): if token not in vocab: vocab[token] = len(vocab)

return vocab

